              <div className="ad-grid">{filtered.map(ad=><AdCard key={ad.id} ad={ad} liked={favorites.includes(ad.id)} onOpen={()=>{setSelected(ad);setViewHistory(old=>[ad.id,...old.filter(id=>id!==ad.id)]);setAds(old=>old.map(x=>x.id===ad.id?{...x,views:x.views+1}:x));}} onLike={()=>toggleFavorite(ad.id)} onReport={()=>setReportTarget(ad)}/>)}</div>
              {filtered.length===0 && <div className="empty-state"><Search size={30}/><h3>Ничего не найдено</h3><p>Попробуй изменить запрос или категорию.</p><button className="secondary-button" onClick={resetFilters}>Сбросить фильтры</button></div>}

